//! Stable diagnostic codes: the official analyzer code set dartq aligns to,
//! plus dartq's own `dartq/` namespace.
//!
//! The official set is generated at build time from two tables:
//!
//! - `data/analyzer-codes.tsv` — the full upstream analyzer registry
//!   (generated by `tools/upstream-gen`'s `analyzer-codes-gen` from the
//!   pinned SDK tree's consolidated registry) — backs [`OFFICIAL_CODES`],
//!   the per-code constants outside the syntax tier, and the published-docs
//!   name list behind `analyzer_docs`;
//! - `data/syntax-codes.tsv` — the dart 3.13.1 oracle-locked syntax tier —
//!   backs [`SYNTAX_CODES`] (the prefix of [`OFFICIAL_CODES`]), the
//!   syntax-tier constants, [`OFFICIAL_CODE_DATA`], and
//!   [`message_template`].
//!
//! To update either table, regenerate or edit the TSV and rebuild; the
//! constants and slices are re-derived. Only codes outside the registry —
//! the `prefer_single_quotes` lint (lints never enter the analyzer
//! registry; the lint face is #2676) and the dartq-own `dartq/` namespace —
//! are hand-written below.

use rustc_hash::FxHashMap;

use crate::model::DiagnosticType;

/// A stable diagnostic code: official `snake_case` name, its `UPPERCASE` machine
/// form, the diagnostic family it belongs to, and whether the official
/// documentation page is published.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct CodeInfo {
    /// Official code name, `snake_case`, one-to-one with the analyzer's
    /// `analyzerCode` (e.g. `expected_token`); dartq-own codes carry the
    /// `dartq/` prefix (e.g. `dartq/internal_error`).
    pub name: &'static str,
    /// `UPPERCASE` form as emitted in the machine format's `CODE` field
    /// (e.g. `EXPECTED_TOKEN`).
    pub machine: &'static str,
    /// The diagnostic family this code belongs to.
    pub dtype: DiagnosticType,
    /// Whether the analyzer registry marks this code `hasPublishedDocs: true`.
    /// The oracle's JSON `documentation` field (`errors.dart` `url` getter)
    /// exists only for published codes; dartq-own codes are always `false`.
    pub has_published_docs: bool,
}

impl CodeInfo {
    /// Creates a code descriptor.
    #[must_use]
    pub const fn new(
        name: &'static str,
        machine: &'static str,
        dtype: DiagnosticType,
        has_published_docs: bool,
    ) -> Self {
        Self {
            name,
            machine,
            dtype,
            has_published_docs,
        }
    }
}

/// The upstream analyzer registry class a code belongs to — the declaring
/// registry of the pinned SDK's consolidated diagnostic table (the `class`
/// column of `data/analyzer-codes.tsv`): the coarse provenance of *who*
/// reports the code. Parser/scanner recovery, the analyzer's compile-time
/// and warning registries, the options/pubspec/manifest configuration
/// registries, the ffi/js interop registries, and the todo tags.
///
/// `FeAnalyzerShared` is the shared front-end package's parser registry
/// (the `_fe_analyzer_shared` class): its rows report exactly like the
/// `ParserErrorCode` family — the class distinction is upstream packaging,
/// not behavior.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CodeFamily {
    /// `CompileTimeErrorCode` — declaration, type, and constraint errors.
    CompileTimeErrorCode,
    /// `StaticWarningCode` — the static-analysis warning registry.
    StaticWarningCode,
    /// `WarningCode` — the general warning registry (unused rows, flow
    /// rows, style rows).
    WarningCode,
    /// `HintCode` — advisory hints.
    HintCode,
    /// `TodoCode` — TODO/FIXME/HACK/UNDONE comment tags.
    TodoCode,
    /// `ParserErrorCode` — parser recovery rows.
    ParserErrorCode,
    /// `ScannerErrorCode` — scanner recovery rows.
    ScannerErrorCode,
    /// `_fe_analyzer_shared` — the shared front-end package's parser
    /// registry (see the type docs).
    FeAnalyzerShared,
    /// `PubspecWarningCode` — pubspec.yaml configuration rows.
    PubspecWarningCode,
    /// `ManifestWarningCode` — build manifest configuration rows.
    ManifestWarningCode,
    /// `AnalysisOptionsErrorCode` — analysis options ERROR rows.
    AnalysisOptionsErrorCode,
    /// `AnalysisOptionsWarningCode` — analysis options WARNING rows.
    AnalysisOptionsWarningCode,
    /// `FfiCode` — `dart:ffi` binding rows.
    FfiCode,
    /// `JsInteropCode` — JS interop binding rows.
    JsInteropCode,
}

/// The upstream registry class of an official code, by exact name.
///
/// The generated [`CODE_FAMILIES`] table behind this lookup is emitted
/// from the same TSV parse as [`OFFICIAL_CODES`], so every registry code
/// resolves and a miss is exactly the non-registry population: lint codes
/// (pkg/linter carries its own registry), plugin rows, and the dartq-own
/// `dartq/` namespace.
#[must_use]
pub fn family(name: &str) -> Option<CodeFamily> {
    let index = CODE_FAMILIES
        .binary_search_by(|(known, _)| (*known).cmp(name))
        .ok()?;
    Some(CODE_FAMILIES[index].1)
}

// Per-code doc comments embed verbatim oracle message text — data, not
// prose we may reformat, so doc-text lints are exempt.
#[expect(clippy::doc_markdown)]
mod generated_syntax {
    include!(concat!(env!("OUT_DIR"), "/syntax_codes_generated.rs"));
}

#[expect(clippy::doc_markdown)]
mod generated_analyzer {
    include!(concat!(env!("OUT_DIR"), "/analyzer_codes_generated.rs"));
}

pub use generated_analyzer::*;
pub use generated_syntax::*;

// The `invalid_language_version_override` row keeps the vintage registry's
// representative variant template (AT_SIGN — "The Dart language version
// override number must begin with '@dart'."). dartq's production emission is
// the GREATER variant, whose text is pinned at its emit sites
// (dartq-engine/dartq-cli); both variant texts are in analyzer-8.4.1
// `error/codes.g.dart` — AT_SIGN 11527-11540, GREATER 11560-11571.

// The emission-path face of the table is the generated [`message_template`]
// match: emitters whose code rows are byte-pinned against it render from it
// instead of carrying local literals (the dartq-semantic registry-backed rows
// keep their previous emit-site literals as test pins in both crates). Codes
// outside the table keep their emit-site texts: the dartq-own namespace by
// design, `invalid_language_version_override`'s production GREATER variant by
// divergence (see the note above).

// A code's [`DiagnosticType`] is the machine format's TYPE value. Generated
// rows are SYNTACTIC_ERROR (parser/scanner class types), except the
// language-version family typed by registry class: invalid_language_version_
// override is WarningCode-class STATIC_WARNING, while illegal/inconsistent_
// language_version_override are CompileTimeErrorCode-class COMPILE_TIME_ERROR
// (analyzer-8.4.1 codes.g.dart; re-verified in the pinned live registry —
// diagnostic.g.dart:7356-7365 and :7946-7956 vs :9184-9330, dart 3.15 main).
// Codes the oracle routes by hand to COMPILE_TIME_ERROR at emit time (the
// pseudoSharedCode routing) are emit-site decisions, not registry facts.

// The official M0 families (duplicate_definition, uri_does_not_exist,
// undefined_identifier, argument_type_not_assignable,
// refutable_pattern_in_irrefutable_context, unused_local_variable,
// dead_code, await_in_wrong_context) previously lived here as hand-written
// constants — they are generated from data/analyzer-codes.tsv now (the
// per-code constants in `generated_analyzer`); the transition test below
// pins their resolution and shape.

// --- Lints ---
// Lint codes never enter the analyzer registry (upstream DiagnosticType
// has no LINT row in diagnostic.g.dart; lints live in pkg/linter with
// their own generated registry — the lint face's generator is #2676), so
// the one lint the builtin set carries stays hand-written by upstream
// construction, not by choice.

/// `Unnecessary use of double quotes.`
pub const PREFER_SINGLE_QUOTES: CodeInfo = CodeInfo::new(
    "prefer_single_quotes",
    "PREFER_SINGLE_QUOTES",
    DiagnosticType::Lint,
    false,
);

// --- dartq-own namespace: never part of the official value set,
// always rendered with type TOOL. ---

/// `package_config` is missing or stale; deep analysis is withheld.
pub const DARTQ_PACKAGE_CONFIG_OUT_OF_DATE: CodeInfo = CodeInfo::new(
    "dartq/package_config_out_of_date",
    "DARTQ/PACKAGE_CONFIG_OUT_OF_DATE",
    DiagnosticType::Tool,
    false,
);
/// No `package_config.json` was found; analysis runs degraded on the
/// `BasicWorkspace` floor with every `package:` import unresolved (the
/// oracle's no-config posture — it analyzes, it does not refuse).
pub const DARTQ_PACKAGE_CONFIG_MISSING: CodeInfo = CodeInfo::new(
    "dartq/package_config_missing",
    "DARTQ/PACKAGE_CONFIG_MISSING",
    DiagnosticType::Tool,
    false,
);
/// `package_config.json` exists but is unusable (malformed JSON, duplicate
/// package names); analysis runs on the `Packages.empty` floor with every
/// `package:` import unresolved (the oracle's parse-failure catch-all — it
/// analyzes, it does not refuse).
pub const DARTQ_PACKAGE_CONFIG_INVALID: CodeInfo = CodeInfo::new(
    "dartq/package_config_invalid",
    "DARTQ/PACKAGE_CONFIG_INVALID",
    DiagnosticType::Tool,
    false,
);
/// An internal panic/bug was downgraded to a per-file diagnostic.
pub const DARTQ_INTERNAL_ERROR: CodeInfo = CodeInfo::new(
    "dartq/internal_error",
    "DARTQ/INTERNAL_ERROR",
    DiagnosticType::Tool,
    false,
);
/// A memory-budget downgrade step fired.
pub const DARTQ_MEMORY_DEGRADED: CodeInfo = CodeInfo::new(
    "dartq/memory_degraded",
    "DARTQ/MEMORY_DEGRADED",
    DiagnosticType::Tool,
    false,
);
/// A build-generated source is imported but missing.
pub const DARTQ_MISSING_GENERATED_SOURCE: CodeInfo = CodeInfo::new(
    "dartq/missing_generated_source",
    "DARTQ/MISSING_GENERATED_SOURCE",
    DiagnosticType::Tool,
    false,
);
/// A plugin process died or broke the wire contract (crash and
/// memory isolation; the restart budget's exhaustion is the terminal form).
pub const DARTQ_PLUGIN_CRASHED: CodeInfo = CodeInfo::new(
    "dartq/plugin_crashed",
    "DARTQ/PLUGIN_CRASHED",
    DiagnosticType::Tool,
    false,
);
/// A plugin overran a wall-clock deadline (handshake/shutdown request budget
/// or the per-callback budget on `request/fixes`); the child is killed
///.
pub const DARTQ_PLUGIN_TIMEOUT: CodeInfo = CodeInfo::new(
    "dartq/plugin_timeout",
    "DARTQ/PLUGIN_TIMEOUT",
    DiagnosticType::Tool,
    false,
);
/// A submitted source exceeds the analysis capacity limit and is excluded
/// from analysis; an advisory row names the rejected file.
pub const DARTQ_SOURCE_REJECTED: CodeInfo = CodeInfo::new(
    "dartq/source_rejected",
    "DARTQ/SOURCE_REJECTED",
    DiagnosticType::Tool,
    false,
);

/// The hand-written codes above: the one lint outside the analyzer
/// registry plus the dartq-own namespace. Every other builtin code is
/// generated from the TSV tables.
const OWN_CODES: [CodeInfo; 10] = [
    PREFER_SINGLE_QUOTES,
    DARTQ_PACKAGE_CONFIG_OUT_OF_DATE,
    DARTQ_PACKAGE_CONFIG_MISSING,
    DARTQ_PACKAGE_CONFIG_INVALID,
    DARTQ_INTERNAL_ERROR,
    DARTQ_MEMORY_DEGRADED,
    DARTQ_MISSING_GENERATED_SOURCE,
    DARTQ_PLUGIN_CRASHED,
    DARTQ_PLUGIN_TIMEOUT,
    DARTQ_SOURCE_REJECTED,
];

/// Name → [`CodeInfo`] lookup over the builtin code set (generated official
/// table + hand-written own codes).
///
/// Build once at startup via [`CodeRegistry::builtin`]; lookups are then plain
/// map hits. Keys are exact code names (`snake_case`; dartq-own names include
/// the `dartq/` prefix).
#[derive(Debug, Clone)]
pub struct CodeRegistry {
    by_name: FxHashMap<&'static str, CodeInfo>,
}

impl CodeRegistry {
    /// Builds the registry over all builtin codes.
    #[must_use]
    pub fn builtin() -> Self {
        Self {
            by_name: OFFICIAL_CODES
                .iter()
                .copied()
                .chain(OWN_CODES)
                .map(|c| (c.name, c))
                .collect(),
        }
    }

    /// Looks a code up by exact name.
    #[must_use]
    pub fn get(&self, name: &str) -> Option<CodeInfo> {
        self.by_name.get(name).copied()
    }

    /// Iterates all builtin codes in unspecified order.
    pub fn iter(&self) -> impl Iterator<Item = CodeInfo> + '_ {
        self.by_name.values().copied()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Table shape: the syntax tier keeps its 259 rows (255 registry-gated
    /// syntax codes + 4 supplemental rows, the 7 measured-dead rows pruned
    /// in #222) and is the exact prefix of the full official table (the
    /// upstream registry rows follow in name-sorted order); names are
    /// globally unique, machine forms are the uppercase names, and every
    /// row is reachable through the registry next to the hand-written own
    /// codes.
    #[test]
    fn generated_table_is_complete_and_wellformed() {
        assert_eq!(SYNTAX_CODES.len(), 259);
        assert_eq!(OFFICIAL_CODE_DATA.len(), SYNTAX_CODES.len());
        assert!(OFFICIAL_CODES.len() > SYNTAX_CODES.len());
        for (syntax, official) in SYNTAX_CODES.iter().zip(OFFICIAL_CODES) {
            assert_eq!(syntax, official, "{}: not the table prefix", syntax.name);
        }
        let registry = CodeRegistry::builtin();
        let mut names: Vec<&str> = OFFICIAL_CODES.iter().map(|c| c.name).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), OFFICIAL_CODES.len());
        for code in OFFICIAL_CODES {
            assert_eq!(code.machine, code.name.to_uppercase());
            assert_eq!(registry.get(code.name), Some(*code));
        }
        for code in OWN_CODES {
            assert_eq!(registry.get(code.name), Some(code));
        }
        assert_eq!(
            registry.iter().count(),
            OFFICIAL_CODES.len() + OWN_CODES.len()
        );
    }

    /// The family table is the registry's own class column: same name set
    /// as `OFFICIAL_CODES` (both derive from the one TSV parse, so an
    /// official code never misses), table order strictly name-sorted (the
    /// binary search's precondition), every variant the pin's registry
    /// carries is populated (the 3.13.7 pin has no `JsInteropCode` rows —
    /// the variant stays for the upstream class universe and the
    /// dartq-ai explain face — and is the one unpopulated family), and a
    /// miss is exactly the non-registry population — lint codes, plugin
    /// rows, and the dartq-own namespace.
    #[test]
    fn family_table_covers_the_official_registry() {
        assert_eq!(CODE_FAMILIES.len(), OFFICIAL_CODES.len());
        let mut names: Vec<&str> = OFFICIAL_CODES.iter().map(|c| c.name).collect();
        names.sort_unstable();
        for (name, (known, _)) in names.iter().zip(CODE_FAMILIES) {
            assert_eq!(name, known);
        }
        for window in CODE_FAMILIES.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "{} !< {}",
                window[0].0,
                window[1].0
            );
        }
        let distinct: rustc_hash::FxHashSet<CodeFamily> =
            CODE_FAMILIES.iter().map(|(_, f)| *f).collect();
        assert_eq!(
            distinct.len(),
            13,
            "every CodeFamily variant the pin's registry carries is populated \
             (JsInteropCode is the 3.13.7-empty one)"
        );
        for name in ["prefer_single_quotes", "dartq/internal_error", "plug_lint"] {
            assert_eq!(family(name), None, "{name}: non-registry code");
        }
    }

    /// Spot pins over every registry class: parser/scanner/shared recovery
    /// rows, the options registries, the warning registries, and the
    /// config-file registries. `removed_lint_use` is `WarningCode`-classed
    /// upstream (dartq-ai's explain face overrides its bucket to
    /// options-config — pinned there), and the language-version rows keep
    /// their class-derived typing (`invalid_language_version_override` is
    /// `WarningCode`).
    #[test]
    fn family_spot_pins_per_registry_class() {
        let expected: [(&str, CodeFamily); 14] = [
            ("expected_token", CodeFamily::ParserErrorCode),
            ("unterminated_string_literal", CodeFamily::ScannerErrorCode),
            (
                "missing_const_final_var_or_type",
                CodeFamily::FeAnalyzerShared,
            ),
            ("undefined_identifier", CodeFamily::CompileTimeErrorCode),
            ("invalid_language_version_override", CodeFamily::WarningCode),
            ("dead_code", CodeFamily::WarningCode),
            ("dead_null_aware_expression", CodeFamily::StaticWarningCode),
            ("unused_import", CodeFamily::WarningCode),
            ("removed_lint_use", CodeFamily::WarningCode),
            ("undefined_lint", CodeFamily::AnalysisOptionsWarningCode),
            (
                "included_file_parse_error",
                CodeFamily::AnalysisOptionsErrorCode,
            ),
            ("asset_does_not_exist", CodeFamily::PubspecWarningCode),
            ("todo", CodeFamily::TodoCode),
            ("abi_specific_integer_invalid", CodeFamily::FfiCode),
        ];
        for (name, want) in expected {
            assert_eq!(family(name), Some(want), "{name}");
        }
    }

    /// Transition proof (#2677): the syntax tier is byte-equal to the
    /// checked-in `data/syntax-codes.tsv` (itself content-pinned by the
    /// blake3 test in tests/syntax_codes_tsv.rs) on every shared column —
    /// generalizing build.rs to the full registry table must not move one
    /// byte of the syntax tier's generated output.
    #[test]
    fn syntax_tier_is_byte_equal_to_the_pinned_tsv() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("data/syntax-codes.tsv");
        let raw = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{e}"));
        let rows: Vec<Vec<&str>> = raw
            .lines()
            .filter(|line| !line.is_empty() && !line.starts_with('#'))
            .map(|line| line.split('\t').collect())
            .collect();
        assert_eq!(rows.len(), SYNTAX_CODES.len());
        for (fields, code) in rows.iter().zip(SYNTAX_CODES) {
            let [name, machine, sev, _source, message, published] = fields[..] else {
                panic!("{}: expected 6 columns", code.name);
            };
            assert_eq!(code.name, name);
            assert_eq!(code.machine, machine);
            let published = published == "true";
            assert_eq!(code.has_published_docs, published);
            let data = OFFICIAL_CODE_DATA
                .iter()
                .find(|(n, ..)| *n == name)
                .unwrap_or_else(|| panic!("{name}: no data row"));
            assert_eq!(data.1, sev);
            assert_eq!(data.2, message);
            assert_eq!(data.3, published);
            assert_eq!(message_template(name), Some(message));
        }
    }

    /// The M0-measured official families previously lived here as
    /// hand-written constants; they resolve from the generated registry
    /// table now (the #2677 migration). Every former hand-written official
    /// name must exist in `OFFICIAL_CODES` with the shape the constants
    /// carried — dtype and published flag included.
    #[test]
    fn official_m0_families_resolve_from_the_generated_table() {
        let expected = [
            (
                "duplicate_definition",
                DiagnosticType::CompileTimeError,
                true,
            ),
            (
                "await_in_wrong_context",
                DiagnosticType::CompileTimeError,
                false,
            ),
            ("uri_does_not_exist", DiagnosticType::CompileTimeError, true),
            (
                "undefined_identifier",
                DiagnosticType::CompileTimeError,
                true,
            ),
            (
                "argument_type_not_assignable",
                DiagnosticType::CompileTimeError,
                true,
            ),
            (
                "refutable_pattern_in_irrefutable_context",
                DiagnosticType::CompileTimeError,
                true,
            ),
            ("unused_local_variable", DiagnosticType::StaticWarning, true),
            ("dead_code", DiagnosticType::StaticWarning, true),
        ];
        for (name, dtype, published) in expected {
            let code = OFFICIAL_CODES
                .iter()
                .find(|c| c.name == name)
                .unwrap_or_else(|| panic!("{name} missing from the generated registry table"));
            assert_eq!(code.dtype, dtype, "{name}");
            assert_eq!(code.has_published_docs, published, "{name}");
            assert_eq!(code.machine, name.to_uppercase(), "{name}");
        }
        // The constants the migration replaced keep resolving to those rows.
        assert_eq!(DUPLICATE_DEFINITION.name, "duplicate_definition");
        assert_eq!(URI_DOES_NOT_EXIST.name, "uri_does_not_exist");
    }

    /// Audit F7: every `SYNTACTIC_ERROR` code carries oracle severity ERROR
    /// (so emitters must emit severity `Error`), the oracle-WARNING row is
    /// the static-warning family, and ERROR rows never carry a warning
    /// family. TYPE follows the oracle registry class, not per-row severity:
    /// `illegal/inconsistent_language_version_override` are `CompileTime`-
    /// `ErrorCode` entries (diagnostic.g.dart:7356-7365 and :7946-7956, ERROR +
    /// `COMPILE_TIME_ERROR`) while `invalid_language_version_override` is
    /// `WarningCode` (diagnostic.g.dart:9184-9330, WARNING + `STATIC_WARNING`) —
    /// severity alone does not decide the family.
    #[test]
    fn dtype_matches_oracle_severity() {
        let registry = CodeRegistry::builtin();
        for (name, sev, _, _) in OFFICIAL_CODE_DATA {
            let code = registry.get(name).expect("code present in table");
            match *sev {
                "WARNING" => {
                    assert_eq!(code.dtype, DiagnosticType::StaticWarning, "{name}");
                }
                "ERROR" => {
                    assert_ne!(
                        code.dtype,
                        DiagnosticType::StaticWarning,
                        "{name}: ERROR rows are never STATIC_WARNING-typed"
                    );
                }
                other => panic!("{name}: unknown oracle SEV {other:?}"),
            }
            if code.dtype == DiagnosticType::SyntacticError {
                assert_eq!(
                    *sev, "ERROR",
                    "{name}: SYNTACTIC_ERROR codes must be oracle-ERROR"
                );
            }
        }
        // Audit #170 F1/F2 pin: the two ERROR-level language-version rows are
        // CompileTimeErrorCode (COMPILE_TIME_ERROR), not WarningCode.
        for name in [
            "illegal_language_version_override",
            "inconsistent_language_version_override",
        ] {
            assert_eq!(
                registry.get(name).expect(name).dtype,
                DiagnosticType::CompileTimeError,
                "{name}"
            );
        }
        assert_eq!(
            registry
                .get("invalid_language_version_override")
                .expect("present")
                .dtype,
            DiagnosticType::StaticWarning
        );
    }

    /// [`DiagnosticType::severity`] maps each family to its oracle severity:
    /// `SYNTACTIC_ERROR` / `COMPILE_TIME_ERROR` rows are oracle-ERROR,
    /// `STATIC_WARNING` rows oracle-WARNING, `LINT` rows oracle-INFO, and
    /// `Tool` — the dartq-own per-code fallback — stays ERROR.
    #[test]
    fn dtype_severity_maps_oracle_families() {
        use crate::model::Severity;

        assert_eq!(DiagnosticType::SyntacticError.severity(), Severity::Error);
        assert_eq!(DiagnosticType::CompileTimeError.severity(), Severity::Error);
        assert_eq!(DiagnosticType::StaticWarning.severity(), Severity::Warning);
        assert_eq!(DiagnosticType::Lint.severity(), Severity::Info);
        // dartq-own fallback: `dartq/` tool diagnostics are ERROR.
        assert_eq!(DiagnosticType::Tool.severity(), Severity::Error);
    }

    /// Message templates: placeholders are consecutive from `{0}` and never
    /// exceed the measured upper bound of 1 (2 arguments, e.g.
    /// `conflicting_modifiers`); literal braces must survive untouched.
    /// Mirrors build.rs `placeholders`: a `{`, digit run, `}` scan, so
    /// multi-digit indices (`{10}`) are visible here too.
    #[test]
    fn message_placeholders_are_consecutive_and_bounded() {
        for (name, _, message, _) in OFFICIAL_CODE_DATA {
            let mut highest: u32 = 0;
            for (index, _) in placeholder_spans(message) {
                assert!(
                    index <= 1,
                    "{name}: placeholder index {index} out of bounds"
                );
                assert_eq!(index, highest, "{name}: placeholders must be consecutive");
                highest = index + 1;
            }
        }
        assert_eq!(
            message_template("named_parameter_outside_group"),
            Some("Named parameters must be enclosed in curly braces ('{' and '}').")
        );
    }

    /// `(index, byte offset)` of every `{N}` placeholder — the test-module
    /// twin of build.rs `placeholders` (single pass, digit run between `{`
    /// and `}`, multi-digit indices included).
    fn placeholder_spans(message: &str) -> Vec<(u32, usize)> {
        let bytes = message.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'{' {
                let digits = bytes[i + 1..]
                    .iter()
                    .take_while(|&&b| b.is_ascii_digit())
                    .count();
                if digits > 0 && bytes.get(i + 1 + digits) == Some(&b'}') {
                    let index: u32 = message[i + 1..i + 1 + digits]
                        .parse()
                        .expect("ASCII digits fit u32");
                    out.push((index, i));
                    i += digits + 2;
                    continue;
                }
            }
            i += 1;
        }
        out
    }

    /// Audit A5: the scan must see multi-digit placeholders and skip literal
    /// braces exactly like the build-time validator (the build.rs twin is
    /// exercised by every rebuild over the real TSV).
    #[test]
    fn placeholder_scan_handles_multi_digit_and_literals() {
        assert_eq!(placeholder_spans("{0} and {1}"), vec![(0, 0), (1, 8)]);
        assert_eq!(placeholder_spans("up to {10}"), vec![(10, 6)]);
        assert_eq!(placeholder_spans("{' literal {} brace"), vec![]);
        assert_eq!(placeholder_spans("{0x} {-1} {x0}"), vec![]);
        assert_eq!(placeholder_spans("{{0}}"), vec![(0, 1)]);
    }

    /// The 19 pre-generation constants keep their exact name, machine form
    /// and family across the migration.
    #[test]
    fn legacy_constants_keep_their_shape() {
        let registry = CodeRegistry::builtin();
        let expected: [(&str, DiagnosticType); 19] = [
            ("expected_token", DiagnosticType::SyntacticError),
            ("missing_identifier", DiagnosticType::SyntacticError),
            (
                "unterminated_string_literal",
                DiagnosticType::SyntacticError,
            ),
            ("break_outside_of_loop", DiagnosticType::SyntacticError),
            ("encoding", DiagnosticType::SyntacticError),
            (
                "unexpected_dollar_in_string",
                DiagnosticType::SyntacticError,
            ),
            ("duplicate_definition", DiagnosticType::CompileTimeError),
            ("await_in_wrong_context", DiagnosticType::CompileTimeError),
            ("uri_does_not_exist", DiagnosticType::CompileTimeError),
            ("undefined_identifier", DiagnosticType::CompileTimeError),
            (
                "argument_type_not_assignable",
                DiagnosticType::CompileTimeError,
            ),
            ("unused_local_variable", DiagnosticType::StaticWarning),
            (
                "invalid_language_version_override",
                DiagnosticType::StaticWarning,
            ),
            ("dead_code", DiagnosticType::StaticWarning),
            ("prefer_single_quotes", DiagnosticType::Lint),
            ("dartq/package_config_out_of_date", DiagnosticType::Tool),
            ("dartq/internal_error", DiagnosticType::Tool),
            ("dartq/memory_degraded", DiagnosticType::Tool),
            ("dartq/missing_generated_source", DiagnosticType::Tool),
        ];
        for (name, dtype) in expected {
            assert_eq!(registry.get(name).expect(name).dtype, dtype, "{name}");
        }
    }

    #[test]
    fn message_template_lookup() {
        assert_eq!(
            message_template("expected_token"),
            Some("Expected to find '{0}'.")
        );
        assert_eq!(message_template("no_such_code"), None);
        // dartq-own codes are not in the official table.
        assert_eq!(message_template("dartq/internal_error"), None);
    }

    /// The generated match face can never drift from the data table: every
    /// row's name resolves to exactly its template. The dartq-semantic
    /// `SemanticCode::message` arms wired to the registry additionally pin
    /// their previous emit-site literals byte-for-byte — the migration's
    /// byte-identity proof on the registry side (the emission-side pins live
    /// in dartq-semantic's `messages_are_verbatim`).
    #[test]
    fn message_template_covers_the_table_and_pins_emit_rows() {
        for (name, _, message, _) in OFFICIAL_CODE_DATA {
            assert_eq!(message_template(name), Some(*message), "{name}");
        }
        assert_eq!(
            message_template("wrong_number_of_parameters_for_setter"),
            Some("Setters must declare exactly one required positional parameter.")
        );
        assert_eq!(
            message_template("member_with_class_name"),
            Some("A class member can't have the same name as the enclosing class.")
        );
        assert_eq!(
            message_template("expected_representation_type"),
            Some("Expected a representation type.")
        );
    }

    /// Audit F1: exactly 15 published codes among the 259 table rows — the 13
    /// `hasPublishedDocs: true` syntax codes (captured from analyzer-8.4.1
    /// `syntactic_errors.g.dart`, re-verified in the pinned live registry
    /// `diagnostic.g.dart`, which absorbed the syntactic and scanner rows)
    /// plus `invalid_language_version_override` (all 9 of its variants are
    /// published, diagnostic.g.dart:9184-9330) and
    /// `inconsistent_language_version_override` (:7946-7956);
    /// `illegal_language_version_override` (:7356-7365) and every scanner
    /// code are unpublished — no `hasPublishedDocs` in `diagnostic.g.dart`
    /// (the 8.4.1-vintage `_fe_analyzer_shared-91.0.0` `scanner/errors.g.dart`
    /// is not in the pinned checkout). `expected_token` is unpublished — the
    /// golden tests pin its missing `documentation` key.
    #[test]
    fn published_docs_flags_match_oracle_registry() {
        let is_published = |name: &str| {
            OFFICIAL_CODE_DATA
                .iter()
                .find(|(n, ..)| *n == name)
                .expect("code present in table")
                .3
        };
        assert_eq!(
            OFFICIAL_CODE_DATA
                .iter()
                .filter(|(.., published)| *published)
                .count(),
            15
        );
        for name in [
            "abstract_sealed_class",
            "default_value_in_function_type",
            "empty_record_literal_with_comma",
            "extension_declares_constructor",
            "field_initializer_outside_constructor",
            "record_literal_one_positional_no_trailing_comma",
            "variable_pattern_keyword_in_declaration_context",
            "wrong_number_of_parameters_for_setter",
            "invalid_language_version_override",
            "inconsistent_language_version_override",
        ] {
            assert!(is_published(name), "{name} must be published");
        }
        for name in [
            "expected_token",
            "unterminated_string_literal",
            "encoding",
            "illegal_language_version_override",
        ] {
            assert!(!is_published(name), "{name} must be unpublished");
        }
        // dartq-own codes never carry a published docs page.
        for code in OWN_CODES {
            if code.name.starts_with("dartq/") {
                assert!(!code.has_published_docs, "{}", code.name);
            }
        }
    }

    /// The hand-written constants and the semantic table define the same
    /// official codes independently (the constants feed the golden tests, the
    /// semantic emit path builds its own descriptors), so nothing else ties
    /// them together. Pin the shared-name pairs' string identity here — drift
    /// on either side fails loudly. `DEAD_CODE` and `AWAIT_IN_WRONG_CONTEXT`
    /// have no semantic counterpart: they sit outside the frozen M1 gate set.
    #[test]
    fn hand_written_constants_match_semantic_table() {
        use dartq_semantic::codes::SemanticCode;

        let pairs = [
            (DUPLICATE_DEFINITION, SemanticCode::DuplicateDefinition),
            (UNDEFINED_IDENTIFIER, SemanticCode::UndefinedIdentifier),
            (
                ARGUMENT_TYPE_NOT_ASSIGNABLE,
                SemanticCode::ArgumentTypeNotAssignable,
            ),
        ];
        for (constant, semantic) in pairs {
            let info = semantic.code_info();
            assert_eq!(constant.name, info.name, "{}", constant.machine);
            assert_eq!(constant.machine, info.machine, "{}", constant.name);
        }
    }

    /// The resolution family (dartq-resolution `ResolutionCode`, frozen at
    /// its design freeze) shares official codes with this registry, but
    /// dartq-resolution is not a dependency of this crate, so its 15
    /// public names are pinned here; their membership and machine forms
    /// are decided by the generated table (the #2677 migration replaced
    /// the hand-transcribed name/machine pairs with registry resolution).
    #[test]
    fn resolution_codes_resolve_through_the_generated_table() {
        const RESOLUTION_NAMES: [&str; 15] = [
            "uri_does_not_exist",
            "uri_does_not_exist_in_doc_import",
            "uri_has_not_been_generated",
            "invalid_uri",
            "uri_with_interpolation",
            "use_of_native_extension",
            "import_of_non_library",
            "export_of_non_library",
            "part_of_non_part",
            "part_of_different_library",
            "part_of_unnamed_library",
            "duplicate_part",
            "ambiguous_import",
            "ambiguous_export",
            "shared_deferred_prefix",
        ];
        let registry = CodeRegistry::builtin();
        for name in RESOLUTION_NAMES {
            let code = registry
                .get(name)
                .unwrap_or_else(|| panic!("{name} missing from the generated registry table"));
            assert_eq!(code.machine, name.to_uppercase(), "{name}");
        }
        // The pair that also lives as a generated constant is tied to it.
        assert_eq!(URI_DOES_NOT_EXIST.name, "uri_does_not_exist");
        assert_eq!(URI_DOES_NOT_EXIST.machine, "URI_DOES_NOT_EXIST");
    }
}
